"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[25],{89648:e=>{e.exports=JSON.parse('{"label":"quickstart","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/tags/quickstart","allTagsPath":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/tags","count":5,"items":[{"id":"version-1.0/challenges/overview","title":"Current challenges","description":"Cartesi Rollups are shaped by the contributions and collaborative efforts of its decentralized community. As the community continuously works together to build something amazing, there are ongoing challenges that need attention. On this page, you\u2019ll explore these challenges and potential strategies and solutions that the community might consider.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/challenges/overview"},{"id":"version-1.0/build-dapps/deploying-dapps","title":"Deploying dApps","description":"Cartesi Rollups dApps are intended to be deployed to public blockchains, so that they can be accessed by users. This can be done by taking advantage of a cloud-based infrastructure provided by Cartesi.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/deploying-dapps"},{"id":"version-1.0/build-dapps/overview","title":"Overview","description":"Cartesi\'s vision is that creating a dApp should not be too different from the general development of desktop, web, and mobile applications. To that end, Cartesi provides a framework for building decentralized logic, giving developers full flexibility to use the tools and libraries of their preference.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/overview"},{"id":"version-1.0/build-dapps/run-dapp","title":"Run an example dApp","description":"This article explains how to build and interact with a minimalistic Cartesi Rollups application.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/run-dapp"},{"id":"version-1.0/build-dapps/dapp-host-mode","title":"Run back-end in Host Mode","description":"When developing an application, it is often important to easily test and debug it. For that matter, it is possible to run the Cartesi Rollups environment in host mode, so that the dApp\'s back-end can be executed directly on the host machine, allowing it to be debugged using regular development tools such as an IDE.","permalink":"/CARTESI-docs2/pr-preview/pr-9/cartesi-rollups/1.0/build-dapps/dapp-host-mode"}]}')}}]);